package org.slavicmyths.gorynych;
import java.util.*;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.item.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import org.slavicmyths.client.*;
public final class GorynychChecks {
 private static int checks;
 private static void check(boolean value,String what){checks++;if(!value)throw new AssertionError(what);}
 static int uv(ModelPart part)throws Exception{int count=0;var cubes=ModelPart.class.getDeclaredField("cubes");cubes.setAccessible(true);var children=ModelPart.class.getDeclaredField("children");children.setAccessible(true);var polys=ModelPart.Cube.class.getDeclaredField("polygons");polys.setAccessible(true);for(var cube:(List<?>)cubes.get(part))for(var poly:(Object[])polys.get(cube)){var vertices=poly.getClass().getDeclaredField("vertices");vertices.setAccessible(true);for(var vertex:(Object[])vertices.get(poly)){var u=vertex.getClass().getDeclaredField("u");var v=vertex.getClass().getDeclaredField("v");u.setAccessible(true);v.setAccessible(true);float x=u.getFloat(vertex),y=v.getFloat(vertex);check(Float.isFinite(x)&&Float.isFinite(y)&&x>=0&&x<=1&&y>=0&&y<=1,"native UV in atlas");count++;}}for(var child:((Map<?,?>)children.get(part)).values())count+=uv((ModelPart)child);return count;}
 private static String geometry(ModelPart part)throws Exception{var cubes=ModelPart.class.getDeclaredField("cubes");cubes.setAccessible(true);var children=ModelPart.class.getDeclaredField("children");children.setAccessible(true);var out=new StringBuilder();for(var cube:(List<?>)cubes.get(part))for(String key:List.of("minX","maxX","minY","maxY","minZ","maxZ")){var f=ModelPart.Cube.class.getDeclaredField(key);f.setAccessible(true);out.append(f.getFloat(cube)).append('/');}for(var child:((Map<?,?>)children.get(part)).values())out.append(geometry((ModelPart)child));return out.toString();}
 public static void main(String[] args)throws Exception{
  check(GorynychRules.HP==3600&&GorynychRules.TRANSFORM_HP==1800&&GorynychRules.FLOOR==180,"logical health thresholds");
  for(float hp:new float[]{3600,3000,1800,500,180})for(float damage:new float[]{0,1,10,100,1000,100000,Float.MAX_VALUE}){float remaining=GorynychRules.remaining(hp,damage);check(remaining>=180&&remaining<=hp,"excess damage never lethal");if(damage>=hp-180)check(remaining==180,"arbitrary overkill clamps to exhausted threshold");}
  for(int mask=0;mask<8;mask++)for(int h=0;h<3;h++){int clean=GorynychRules.clean(mask,h);check(clean==(mask|1<<h)&&GorynychRules.clean(clean,h)==clean,"independent and idempotent cleanse");check(GorynychRules.canClean(4,mask,h)==((mask&1<<h)==0),"only new exhausted head consumes reagent");check(!GorynychRules.canClean(1,mask,h)&&!GorynychRules.canClean(6,mask,h),"no combat or purified cleansing");}
  var d=new GorynychLedger();var world=d.world();for(var rotation:Rotation.values())for(int mask=0;mask<8;mask++){UUID id=UUID.randomUUID();var hill=new CompoundTag();hill.putLong("Origin",new BlockPos(1000,20,-2000).asLong());hill.putString("Rotation",rotation.name());d.ensure(id,hill);var n=d.row(id);n.putInt("Clean",mask);n.putFloat("HP",180);n.putInt("State",mask==7?6:5);n.putBoolean("Wings",true);n.putLong("PopulationAt",12345);UUID player=UUID.randomUUID();d.participant(id,player);GorynychLedger.part(GorynychLedger.part(n,"Rewards"),player.toString()).putBoolean("Claimed",true);
   for(int node=0;node<GorynychPlaces.NODES.length;node++)check(GorynychPlaces.bounds(n).contains(GorynychPlaces.node(n,node)),"rotated patrol node inside exact hill");var loaded=GorynychLedger.load(d.save(new CompoundTag(),null),null);var restored=loaded.row(id);check(loaded.world().equals(world)&&restored.getInt("Clean")==mask&&restored.getFloat("HP")==180&&restored.getBoolean("Wings"),"saved world, health, wings and all eight cleanse masks");check(GorynychLedger.part(restored,"Participants").getBoolean(player.toString()),"participants preserved");check(GorynychLedger.part(GorynychLedger.part(restored,"Rewards"),player.toString()).getBoolean("Claimed")&&!restored.contains("PopulationAt"),"claim retained and local population deadline reset");}
  net.neoforged.fml.loading.LoadingModList.of(List.of(),List.of(),List.of(),List.of(),Map.of());net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();
  var mesh=GorynychMesh.create();int vertices=uv(mesh);check(vertices>=7000,"substantial authored native dragon geometry");var body=mesh.getChild("body");for(int h=0;h<3;h++){var neck=body.getChild("neck_"+h+"_0");for(int i=1;i<5;i++)neck=neck.getChild("neck_"+h+"_"+i);check(neck.getChild("head_"+h).getChild("jaw_"+h)!=null,"three separate articulated neck/skull/jaw hierarchies");}for(String side:List.of("left","right")){check(body.getChild("wing_"+side)!=null,"two independent wings");for(String pos:List.of("front","back"))check(body.getChild("leg_"+pos+"_"+side).getChild("leg_"+pos+"_"+side+"_foot")!=null,"four independently moving feet");}
  Set<String> armorGeometry=new HashSet<>();for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET)){var armor=DragonArmor.create(slot);uv(armor.head);uv(armor.body);uv(armor.leftArm);uv(armor.rightArm);uv(armor.leftLeg);uv(armor.rightLeg);armorGeometry.add(geometry(armor.head)+geometry(armor.body)+geometry(armor.leftArm)+geometry(armor.leftLeg));};check(armorGeometry.size()==4,"separate wearable geometry");
  var source=new ItemStack(Items.DIAMOND_HELMET);source.setDamageValue(80);source.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Personal armor"));var data=new CompoundTag();data.putString("RuneReceipt","kept");source.set(DataComponents.CUSTOM_DATA,CustomData.of(data));var upgraded=GorynychUpgrade.copy(source,Items.NETHERITE_HELMET);check(upgraded.is(Items.NETHERITE_HELMET)&&source.is(Items.DIAMOND_HELMET),"upgrade copy changes output only");check(upgraded.get(DataComponents.CUSTOM_NAME).equals(source.get(DataComponents.CUSTOM_NAME))&&upgraded.get(DataComponents.CUSTOM_DATA).equals(source.get(DataComponents.CUSTOM_DATA)),"custom name and applicable custom components retained");check(upgraded.getDamageValue()==(int)(80./source.getMaxDamage()*upgraded.getMaxDamage()),"wear fraction retained");
  System.out.println("GORYNYCH_OFFLINE_PASS checks="+checks+" nativeUvVertices="+vertices+"; no game/server launches; NBT roundtrip is not relog");
 }
}
